// Secure version of the application with AWS Secrets Manager
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');
const winston = require('winston');
const jwt = require('jsonwebtoken');
const { SecretsManager } = require('aws-sdk');

const app = express();

// Initialize AWS Secrets Manager
const secretsManager = new SecretsManager();

// Fetch secrets from AWS Secrets Manager
const getSecret = async (secretName) => {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
    return JSON.parse(data.SecretString);
  } catch (err) {
    logger.error(`Failed to fetch secret: ${err.message}`);
    throw err;
  }
};

// Security Middleware
app.use(helmet());
app.use(express.json());

// Logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.File({ filename: 'security.log' })],
});

app.use((req, res, next) => {
  logger.info(`Request: ${req.method} ${req.url}`);
  next();
});

// Authentication Middleware
const authenticate = (req, res, next) => {
  const token = req.headers['authorization'];
  if (!token) return res.status(401).send('Access Denied');
  try {
    const verified = jwt.verify(token.split(' ')[1], process.env.JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid Token');
  }
};

// Health Check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Initialize server with secrets
const startServer = async () => {
  try {
    const secrets = await getSecret('my-app-secrets'); // Fetch from AWS Secrets Manager

    // Rate Limiting
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100, // Limit each IP to 100 requests per window
    });
    app.use(limiter);

    // CORS Restrictions
    app.use(cors({ origin: secrets.ALLOWED_ORIGINS.split(',') }));

    // Secure Users Endpoint (Requires Auth)
    app.get('/users', authenticate, (req, res) => {
      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    });

    // Error Handling
    app.use((err, req, res, next) => {
      console.error(err.stack);
      res.status(500).send('Something broke!');
    });

    // Start Server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  } catch (err) {
    logger.error('Failed to start server:', err);
    process.exit(1);
  }
};

startServer();

module.exports = app;

